H,W=14,17
pts=[(3,6),(6,4),(8,1),(8,12),(10,10),(12,8)]
g=[[0]*W for _ in range(H)]
for r,c in pts:g[r][c]=2
# horizontal connector between the two markers on row 8
for c in range(2,12):
    if g[8][c]==0:g[8][c]=3
# Connect every other marker vertically to that horizontal row, preserving seeds
for r,c in pts:
    if r<8:
        for rr in range(r+1,8):
            if g[rr][c]==0:g[rr][c]=3
    elif r>8:
        for rr in range(9,r):
            if g[rr][c]==0:g[rr][c]=3
assert len(g)==14 and all(len(row)==17 for row in g)
print(g)

